INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (201, 2, 1, '打基础：搞懂业务和账', '0-2 个月', '建立完整的企业经营流程认知，能把一笔生意从接单到收款在系统里的每一步讲清楚', '对着一张销售订单，完整口述它在 ERP 里触发的全部单据、库存变动和会计分录，不看资料', '["销售订单到出货收款完整走一遍，涉及哪些模块和单据","MRP 的输入输出是什么，为什么它依赖 BOM 和库存准确性","采购三方匹配是什么，它防的是什么风险","标准成本和实际成本的差异从哪来"]', '["一份完整的订单到收款业务流程图，标注每一步的单据与系统模块","一份 ERP 八大模块职责与数据流向对照笔记"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (202, 2, 2, '上手：能配置能跑通', '2-6 个月', '能在测试环境里独立完成一个模块的完整配置，并带客户关键用户跑通业务闭环', '独立配置一个模块并通过关键用户测试，客户能按配置完成日常业务而不需要顾问在旁', '["物料主数据哪些参数会直接影响 MRP 结果，配错会怎样","库存账实不符你怎么查","月结卡住不能过账，可能有哪些原因","客户要求的功能标准系统没有，你怎么处理"]', '["一个模块的完整配置文档与参数说明","一套关键用户测试用例与测试结果记录","一份主数据整理模板与校验规则清单"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (203, 2, 3, '独立：主导蓝图和上线', '6-18 个月', '能独立负责蓝图设计与上线切换，对项目范围、进度和客户接受度负责', '主持完成一次业务蓝图评审并获客户签字，随后主导数据迁移与上线切换，首次月结顺利关账', '["业务蓝图包含哪些内容，你怎么保证客户签字后不反悔","Fit-Gap 里你判断一个需求不该做的依据是什么","数据迁移你怎么设计校验和回退","上线后账不平，你的排查顺序是什么"]', '["一份通过客户评审的业务蓝图文档","一份带成本估算的 Fit-Gap 差异分析清单","一份数据迁移方案与期初对账报告"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (204, 2, 4, '资深：管项目和做整体方案', '1.5-3 年', '能管理完整项目的范围、进度、成本与客户关系，并输出跨系统的企业级数字化方案', '作为项目负责人交付一个百万级项目，控制在预算与工期内验收，客户愿意签二期', '["项目范围失控的信号有哪些，你怎么控","客户高层和业务部门意见冲突，你站哪边","讲一个你做过的 ERP 与其他系统的集成方案","项目延期已成定局，你怎么和客户谈"]', '["一份企业级数字化整体规划方案","一套项目管理模板（计划、风险、变更、验收）","一份跨系统集成架构设计文档"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (301, 3, 1, '打基础：懂业务也懂库', '0-2 个月', '能读懂 MES 的数据库结构和业务含义，知道每张核心表存什么、和哪些业务动作对应', '拿到一套 MES 的库表结构，能自己画出工单、物料、报工、质检四条主线的表关系图并说明业务含义', '["MES 里工单、工序、报工三者的数据关系怎么设计","一条报工记录应该包含哪些字段，为什么","INNER JOIN 和 LEFT JOIN 的结果差异在业务上意味着什么","怎么在 Linux 上查看一个服务的实时日志"]', '["一份 MES 核心表关系图与字段业务含义说明","一份常用查询练习集，覆盖工单、报工、库存三类场景"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (302, 3, 2, '上手：能接需求能交付', '2-6 个月', '能独立完成中小型定制需求的开发与自测，交付的功能不因明显逻辑错误被打回', '独立交付三个定制报表和一个数据接口，上线后一个月内无重大缺陷', '["一张报表数据翻倍了，可能是什么原因","怎么设计一个接口保证重复调用不会产生重复数据","生产环境要改一批数据，你的操作步骤是什么","客户提的需求你觉得不合理，你怎么沟通"]', '["三个定制报表的取数逻辑说明与 SQL","一个数据接口的接口文档与测试用例","一份带事务与回退的数据修正脚本模板"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (303, 3, 3, '独立：能设计能优化', '6-18 个月', '能独立设计一个定制模块的技术方案，并对系统性能与线上稳定性负责', '独立设计并交付一个跨系统集成模块，同时完成一次慢查询治理，把核心看板响应时间降到秒级', '["一条查询从 10 秒优化到 1 秒，你的排查和优化路径是什么","复合索引的最左前缀是什么意思，什么情况下索引会失效","接口调用失败怎么设计重试和补偿，怎么保证不重复","定时任务没执行，你怎么排查"]', '["一份集成模块的技术设计文档，含数据流、异常处理与对账机制","一份性能优化报告，含优化前后的执行计划与耗时对比","一套数据质量校验脚本与巡检机制"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (304, 3, 4, '资深：定架构和技术标准', '1.5-3 年', '能为多项目复用制定技术架构与开发规范，主导复杂集成与大规模数采场景的技术决策', '主导一次平台级技术改造或一个大规模数采项目落地，并建立团队开发规范被实际执行', '["系统上线两年后越来越慢，你怎么做整体治理","怎么设计一套能同时支撑十几个客户个性化需求的架构","讲一次你主导的技术选型，取舍依据是什么","怎么让团队的开发规范真正被执行而不是文档躺着"]', '["一份平台级技术架构设计与演进路线","一套团队开发规范与代码审查清单","一份大规模数采场景的容量评估与技术方案"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (401, 4, 1, '打基础：懂设备也懂网络', '0-2 个月', '能看懂点表和网络拓扑，知道一个设备信号从传感器到系统要经过哪几层', '对着一台陌生设备的电气图和点表，说出它有哪些可采集信号、每个信号代表什么状态、该用什么方式接入', '["PLC 的扫描周期是什么，它对数据采集有什么影响","数字量和模拟量的区别，各自典型采集什么","工业以太网和普通以太网有什么不同","设备状态用哪些信号组合来判断运行、停机、故障"]', '["一份设备信号清单与采集方式建议","一份车间网络拓扑草图，标注每段的介质与协议"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (402, 4, 2, '上手：能调通一台设备', '2-6 个月', '能独立完成单台或几台设备的数据采集配置，从物理连接到数据入库全程自己搞定', '独立把一台陌生设备的数据采集到系统里，数据与现场实际值一致，连续运行一周无异常断流', '["Modbus 寄存器地址和文档地址差 1 是怎么回事","OPC UA 相比传统 OPC 好在哪，订阅怎么配","设备数据每天定时断一次，你怎么查","怎么验证采上来的数据是准确的"]', '["一份设备接入的完整配置文档与连通测试记录","一份数据准确性比对报告","一份抓包分析记录，说明一次通讯问题的定位过程"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (403, 4, 3, '独立：能设计一条产线的数采', '6-18 个月', '能独立完成整条产线的数采方案设计与实施，包含协议选型、点表制定、握手设计和异常处理', '独立交付一条产线的完整数采，稼动率数据可直接用于生产例会，现场认可数据可信', '["一条产线设备品牌五花八门，你怎么统一接入","MES 要下发配方到设备，握手协议你怎么设计才不会卡死","网络断了两小时，这期间的数据怎么办","客户说稼动率算得不对，你怎么排查"]', '["一份产线数采方案，含协议选型依据与网络拓扑","一份完整点表与地址规划文档","一份 MES 与设备的握手协议设计说明"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (404, 4, 4, '资深：做全厂数采架构', '1.5-3 年', '能为全厂或多厂区设计数采与 OT 网络架构，对数据完整性、链路可靠性和长期可运维性负责', '主导一个全厂级设备联网项目落地，设备接入率与数据完整率达标并稳定运行半年以上', '["新建工厂让你规划 OT 网络，你怎么分段、怎么做冗余","IT 部门要求打补丁，生产不同意停机，你怎么协调","上千个采集点，怎么评估网络和服务器扛不扛得住","多厂区数据要汇总到集团，你的架构怎么设计"]', '["一份全厂 OT 网络与数采架构设计文档","一份 IT/OT 隔离与安全方案","一份数采容量评估报告与边缘节点运维方案"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (501, 5, 1, '打基础：先看懂自家工厂', '0-2 个月', '能完整讲清本企业从接单到出货的业务流程，以及现有系统各自管了哪一段', '独立画出本企业的业务流程与系统现状图，标出信息断点和仍在用手工表格的环节', '["介绍你们公司的生产流程和现有系统","ERP 和 MES 分别解决什么问题，边界在哪","你们目前哪些环节还在用手工表格，问题是什么","怎么判断一个业务部门提的需求是真需求"]', '["一份本企业业务流程与系统现状图","一份手工作业环节清单与痛点记录"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (502, 5, 2, '上手：能提需求能验收', '2-6 个月', '能独立编写业务需求说明并参与厂商方案评审，能对交付内容做实质性验收而不是走过场', '独立主导一个模块的需求提出、方案评审和验收，验收时能指出方案中的实际问题', '["厂商说这个需求要二开加钱，你怎么判断合不合理","验收时你会重点检查什么","主数据整理为什么是甲方的责任而不是厂商的","产品编码规则你会怎么设计"]', '["一份业务需求说明书","一份供应商方案对比评估表","一套验收测试用例与数据核对脚本"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (503, 5, 3, '独立：能管一个项目', '6-18 个月', '能作为甲方项目负责人管理一个系统项目，控制范围与进度并推动内部业务部门真正配合', '作为甲方负责人推动一个系统按期上线，业务部门实际使用率达标而非上线即闲置', '["业务部门不配合数据整理，你怎么推","项目延期了，你作为甲方怎么处理与厂商的关系","系统上线后没人用，可能是什么原因","怎么评估一个项目的实际收益"]', '["一份项目管理计划与风险清单","一份上线切换与培训推广方案","一份上线后的数据核对与使用率分析报告"]');
INSERT OR REPLACE INTO career_stages (id, career_id, stage, title, duration, goal, milestone, interview_points, deliverables) VALUES (504, 5, 4, '资深：做企业数字化规划', '1.5-3 年', '能站在企业整体视角规划系统蓝图与投入节奏，对多系统的协同、数据资产和长期成本负责', '输出并通过管理层评审的三年数字化规划，且首年落地项目按规划完成', '["让你做公司三年数字化规划，你从哪几个维度切入","已有的几个系统数据打不通，你怎么治理","怎么向管理层论证一笔数字化投入的回报","自建团队还是全部外包，你怎么权衡"]', '["一份企业三年数字化规划与年度预算建议","一份跨系统数据治理与主数据管理方案","一份供应商管理与长期运维策略"]');
