INSERT OR REPLACE INTO track_level_chapters (level_id, chapter_id, sort) SELECT 42, 79, 1 WHERE EXISTS (SELECT 1 FROM chapters WHERE id = 79 AND status = 'published');
INSERT OR REPLACE INTO track_level_chapters (level_id, chapter_id, sort) SELECT 53, 80, 0 WHERE EXISTS (SELECT 1 FROM chapters WHERE id = 80 AND status = 'published');
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (1, 101, 21, 'core', '七大模块的概念是这个岗位所有对话的基础词汇，不懂就没法参与需求讨论', 0);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (2, 101, 11, 'important', 'MES 的工单和物料几乎都来自 ERP，不知道上游怎么来的就会在集成时抓瞎', 1);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (3, 101, 31, 'important', '第一次被客户问「这个数字怎么来的」时，能自己查表比等开发回复快一天', 2);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (4, 101, 81, 'optional', '先能看懂现场标签和扫码动作，编码规则设计等到中级阶段再学', 3);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (5, 102, 22, 'core', '配置能力是这个阶段的立身之本，16 章核心知识加 6 章实操是必须啃完的部分', 0);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (6, 102, 32, 'core', '数据整理和导入校验全靠 SQL，导错一批主数据可能让整个测试环境重来', 1);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (7, 102, 81, 'important', '扫码作业是现场最高频的动作，配置时必须知道标签和扫码流程怎么设计', 2);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (8, 102, 12, 'important', '整理主数据时要和客户 ERP 的物料、BOM 对齐，不懂 ERP 参数会把脏数据带进来', 3);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (9, 102, 71, 'optional', '客户环境偶尔需要重启服务或看日志，会基础命令能少求人', 4);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (10, 103, 23, 'core', '需求边界界定、集成设计、上线切换这三件事决定项目成败，是独立带项目的分水岭', 0);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (11, 103, 33, 'important', '上线后数据量涨上来，看板变慢和数据对不上都要自己能定位', 1);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (12, 103, 12, 'important', '对接客户 ERP 时要能和对方顾问平等对话，讲清接口需求和数据口径', 2);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (13, 103, 61, 'important', '现场数据断了先怀疑网络，至少要能画出拓扑并做基本排查，不然只能干等', 3);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (14, 103, 72, 'important', '很多客户没有运维，部署、备份、日志排查都得实施工程师自己兜底', 4);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (15, 103, 91, 'important', '独立带项目后要自己开调研会、写纪要、拿需求确认单签字，缺了这层项目边界守不住，需求会无限追加', 5);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (16, 104, 23, 'core', '复杂项目的方案能力来自对生产形态和集成架构的深度理解，这一级要反复实践加深', 0);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (17, 104, 13, 'important', '做整体数字化方案时要能覆盖 ERP 侧的蓝图与集成，只懂 MES 接不了大单', 1);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (18, 104, 83, 'important', '集团级项目必然涉及统一编码体系和完整追溯链设计，这是方案里的硬骨头', 2);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (19, 104, 62, 'optional', '涉及设备联网的项目里能自己评估网络可行性，减少对第三方的依赖', 3);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (20, 104, 41, 'optional', '能看懂点表、和电气工程师对上话即可，深度调试交给 SCADA 数采岗位', 4);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (21, 104, 92, 'core', '同时管两个以上项目并对交付日期负责，实施计划编制、UAT 组织与上线切换必须能自己扛，这是升项目经理的硬门槛', 5);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (22, 201, 11, 'core', '八大模块的职责与单据流是这个岗位的全部对话基础，必须先建立完整认知框架', 0);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (23, 201, 31, 'important', '客户质疑报表数字时能自己查库验证，是顾问建立专业信任的第一道门槛', 1);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (24, 201, 21, 'optional', '了解车间那一层在干什么，避免把 ERP 的生产模块当成万能，为后续集成打底', 2);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (25, 202, 12, 'core', '主数据治理、MRP 参数、库存事务、成本核算、月结，这五块是顾问的日常战场', 0);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (26, 202, 32, 'important', '数据整理、导入校验、期初对账都要写查询，靠开发排队会拖垮项目进度', 1);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (27, 202, 21, 'important', '客户几乎都会问「以后上 MES 怎么办」，答不上来会显得方案不完整', 2);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (28, 203, 13, 'core', '蓝图设计、Fit-Gap、数据迁移、集成架构，这四项是独立顾问的核心交付能力', 0);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (29, 203, 32, 'core', '期初建账与迁移校验的数据量大且不容出错，必须能自己写脚本逐项对平', 1);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (30, 203, 22, 'important', '设计 ERP 与 MES 的边界与接口时，要能理解车间侧的数据粒度和报工逻辑', 2);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (31, 203, 92, 'important', '独立主导蓝图评审与上线切换，本质是组织工作而非配置工作，计划编制与 UAT 组织的能力决定项目能不能按期收口', 3);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (32, 204, 13, 'core', '项目管理能力必须建立在对 ERP 全模块的掌握上，否则控不住范围也压不住客户的临时需求', 0);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (33, 204, 23, 'important', '企业级方案通常是 ERP 加 MES 一体规划，只会 ERP 会被限制在单系统项目里', 1);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (34, 204, 33, 'important', '系统跑几年后的性能与数据治理问题会找上门，要能给出结构性方案', 2);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (35, 204, 71, 'optional', '客户自建机房部署时能参与讨论环境要求，不至于完全依赖厂商技术', 3);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (36, 204, 93, 'core', 'ERP 项目周期长达半年到一年，范围蔓延与变更管理是利润的生死线，这一级不达标就管不了百万级项目', 4);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (37, 301, 31, 'core', '这个岗位的日常输入输出大部分是 SQL，基础不牢后面每一步都要返工', 0);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (38, 301, 21, 'core', '不懂业务写出来的功能会是「客户说啥做啥」，改三轮还不对，业务认知是省时间的投资', 1);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (39, 301, 71, 'important', '开发环境和测试环境都在 Linux 上，连不上服务器查不了日志就无法自助排查', 2);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (40, 302, 32, 'core', '报表开发的本质就是取数，CTE、窗口函数和 NULL 陷阱是每天都会碰到的东西', 0);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (41, 302, 22, 'core', '配置能做到的事不该写代码，不懂标准功能边界会做大量无用的二开', 1);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (42, 302, 71, 'core', '自己部署自己排查是这个阶段的独立性要求，不能每次都找运维', 2);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (43, 302, 101, 'core', '接需求写代码是这个岗位的定义性动作，读懂已有代码并改对一处逻辑是进入交付状态的最低门槛', 3);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (44, 303, 33, 'core', '数据量上千万后，执行计划、索引设计和预聚合是解决性能问题的唯一手段', 0);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (45, 303, 72, 'core', '部署、定时任务、日志排查、备份恢复是二开人员必须自己扛的运维半径', 1);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (46, 303, 23, 'important', '做集成模块时必须理解接口的业务语义与对账要求，只按字段开发一定出问题', 2);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (47, 303, 61, 'important', '接口连不上时要能先判断是网络还是程序，避免把网络问题当成代码 bug 查半天', 3);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (48, 303, 102, 'core', '独立交付集成模块要求能自己搭工程、写接口、控事务、做自测，这一级是独立开发者的完整能力包', 4);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (49, 304, 33, 'core', '数据架构决策的深度直接决定系统能不能撑到三年后，是这个层级最硬的能力', 0);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (50, 304, 23, 'core', '架构决策必须建立在对业务演进的判断上，只看技术会做出用不了的设计', 1);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (51, 304, 73, 'important', '高可用、监控告警、容量规划是对交付系统长期负责的必要能力', 2);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (52, 304, 62, 'important', '大规模数采项目的瓶颈常常在链路而非代码，要能参与网络与容量的联合评估', 3);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (53, 304, 82, 'important', '扫码与追溯是二开需求的高发区，要懂防错校验和性能约束才能设计对', 4);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (54, 304, 103, 'core', '平台级架构、插件扩展点与多客户版本管理是技术负责人的核心职责，只会写功能带不了团队也撑不住产品演进', 5);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (55, 401, 41, 'core', '点表看不懂就无法与电气工程师协作，这是进入这个岗位的第一道门', 0);
INSERT OR REPLACE INTO career_stage_reqs (id, stage_id, level_id, importance, note, sort) VALUES (56, 401, 61, 'core', '数据传不上来八成是网络问题，连拓扑都画不出就只能靠猜', 1);
